def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid of size N x N initialized with zeros
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[ x - 1 ][ y - 1 ] = value

    # Initialize DP table
    dp = [[0] * N for _ in range(N)]

    # Directions for movement (right, down)
    directions = [(0, 1), (1, 0)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            for dx, dy in directions:
                nx, ny = i + dx, j + dy
                if 0 <= nx < N and 0 <= ny < N:
                    dp[nx][ny] = max(dp[nx][ny], dp[i][j] + grid[nx][ny])

    # Return the maximum sum collected on two paths
    return dp[-1][-1]

