def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn):
            if char == '-':
                continue
            digit = int(char) if char != 'X' else 10
            total += digit * (10 - i)
        return total % 11

    # Remove hyphens and convert to digits
    clean_isbn = isbn.replace('-', '')
    if len(clean_isbn) != 10:
        raise ValueError("Invalid ISBN length")

    # Calculate the checksum digit
    calculated_checksum = calculate_checksum(clean_isbn[:9])

    # Compare calculated checksum with the provided checksum
    provided_checksum = int(clean_isbn[9]) if clean_isbn[9] != 'X' else 10
    if calculated_checksum != provided_checksum:
        # If incorrect, correct the checksum
        correct_isbn = clean_isbn[:9] + ('X' if calculated_checksum == 10 else str(calculated_checksum))
        return '-'.join([correct_isbn[:3], correct_isbn[3:6], correct_isbn[6:10]])
    else:
        return "Right"

def count_passing_ways(n: int, m: int) -> int:
    if not isinstance(n, int) or not isinstance(m, int):
        raise ValueError("Both n and m must be integers.")
    if n < 1 or m < 0:
        raise ValueError("n must be greater than 0 and m must be non-negative.")

    # Initialize a 2D array to store the number of ways to reach each student after m passes
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # There is 1 way to be at each student after 0 passes (doing nothing)
    for i in range(n):
        dp[0][i + 1] = 1

    # Fill the dp array
    for j in range(1, m + 1):
        for i in range(n):
            dp[j][(i - 1) % n + 1] += dp[j - 1][i + 1]
            dp[j][(i + 1) % n + 1] += dp[j - 1][i + 1]

    # The result is the number of ways to be back at the starting student after m passes
    return dp[m][1]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a DP array where dp[i] represents the maximum importance value that can be achieved with a budget of i
    dp = [0] * (n + 1)

    # Iterate over each item
    for price, importance in items:
        # Update the DP array from the back to the front to avoid overwriting values that are still needed
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + importance)

    # The maximum importance value that can be achieved with budget n is stored in dp[n]
    return dp[n]

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = (i + length) % n
            for k in range(i + 1, j + n):
                k %= n
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[0][(n - 1) % n]

