def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff)) if abs(coeff) != 1 else ''
        elif i == 1:
            term = str(abs(coeff)) + 'x' if abs(coeff) != 1 else 'x'
        else:
            term = str(abs(coeff)) + 'x^' + str(i) if abs(coeff) != 1 else 'x^' + str(i)
        if coeff < 0:
            term = '-' + term
        elif terms:
            term = '+' + term
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) < 26:
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

