def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k > n:
        return 0
    return count_partitions_helper(n, k, x, 0)

def count_partitions_helper(n: int, k: int, x: int, start: int) -> int:
    if k == 1:
        return 1 if n >= x else 0
    count = 0
    for i in range(start, n - k * x + 1):
        count += count_partitions_helper(n - i, k - 1, x, i + 1)
    return count

