def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    # Initialize a set to keep track of the cleared areas
    cleared_positions = set()

    # Iterate over each area and mark the cleared positions
    for start, end in areas:
        for pos in range(start, end + 1):
            cleared_positions.add(pos)

    # Calculate the number of remaining trees
    remaining_trees = l - len(cleared_positions)

    # Ensure the result is not negative
    return max(remaining_trees, 0)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if T < 0 or M < 0 or not herbs:
        raise ValueError("Invalid input values")

    # Initialize the dp array where dp[i][j] represents the max value
    # that can be achieved with the first i herbs and j time
    dp = [[0 for _ in range(T + 1)] for _ in range(M + 1)]

    # Fill the dp array
    for i in range(1, M + 1):
        time, value = herbs[i - 1]
        for j in range(1, T + 1):
            if time <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - time] + value)
            else:
                dp[i][j] = dp[i - 1][j]

    # The answer is in dp[M][T]
    return dp[M][T]

