def min_groups(w, n, prices):
    if n % 2 != 0:
        raise ValueError("The number of souvenirs must be even")

    prices.sort()
    result = 0
    i, j = 0, n - 1

    while i <= j:
        if prices[i] + prices[j] <= w:
            i += 1
        result += 1
        j -= 1

    return result

